import { Suspense } from 'react'
import { getProducts } from '@/lib/data'

type CatalogSearchParams = Promise<{ category?: string }>

const labels: Record<string, string> = {
  featured: 'Featured products',
  sale: 'Products on sale',
}

export default function CatalogPage({
  searchParams,
}: {
  searchParams: CatalogSearchParams
}) {
  return (
    <main>
      <h1>Catalog</h1>
      {/* The per-category heading is derived from the URL and rendered into the
          prerendered shell, so it is already present in the prefetched payload
          and shown immediately on navigation. */}
      <CategoryHeading searchParams={searchParams} />
      <Suspense fallback={<p>Loading category...</p>}>
        <CategoryProducts searchParams={searchParams} />
      </Suspense>
    </main>
  )
}

async function CategoryHeading({
  searchParams,
}: {
  searchParams: CatalogSearchParams
}) {
  const { category = 'featured' } = await searchParams
  return <h2>{labels[category] ?? labels.featured}</h2>
}

async function CategoryProducts({
  searchParams,
}: {
  searchParams: CatalogSearchParams
}) {
  const { category = 'featured' } = await searchParams
  const products = await getProducts(category)

  return (
    <ul>
      {products.map((product) => (
        <li key={product}>{product}</li>
      ))}
    </ul>
  )
}

