  slug: string
  label: string
  products: string[]
}

// Cached per category so the data is resolved once and reused. The home page
// and the catalog page both read this at build/prerender time, so each
// category's heading and products are prepared before any click.
export async function getProducts(category: string) {
  'use cache'
  await new Promise((resolve) => setTimeout(resolve, 800))
  return productsByCategory[category] ?? []
}

export async function getCategory(slug: string): Promise<Category> {
  const products = await getProducts(slug)
  return {
    slug,
    label: labelsByCategory[slug] ?? labelsByCategory.featured,
    products,
  }
}

export async function getCategories(): Promise<Category[]> {
  return Promise.all(
    Object.keys(productsByCategory).map((slug) => getCategory(slug))
  )
}

