// `<Link prefetch>` from the home page fetches the complete payload. Selecting
// a category link therefore navigates immediately, showing that category's
// heading and products with no loading state and no server render at click.
export default async function CatalogPage() {
  const categories = await getCategories()

  return (
    <main>
      <h1>Catalog</h1>
      <Suspense fallback={null}>
        <CatalogBrowser categories={categories} />
      </Suspense>
    </main>
  )
}

